import { getRequestEvent } from "$app/server";
import { API_TOKEN_COOKIE_NAME, reauthenticate } from "./cellnoor-client";
import { readConfig } from "./config";

export async function downloadFile({ link, accept }: { link: string; accept: string }) {
  // It'd be nice to use the `CellnoorClient` here, but the Rust library used to generate the OpenAPI document doesn't support HTML as a content type I guess? So the resulting client generated by openapi-ts doesn't have that route either
  await reauthenticate();

  const { apiUrl, publicUrl } = await readConfig();

  const url = `${apiUrl}${link}`;

  const { fetch, request, cookies } = getRequestEvent();

  const headers = apiUrl.startsWith(publicUrl || "")
    ? request.headers
    : {
        Cookie: `${API_TOKEN_COOKIE_NAME}=${cookies.get(API_TOKEN_COOKIE_NAME)}`,
        accept,
      };

  return fetch(url, { headers });
}
